1	/* Methods to compute pixel overlap areas on the sphere.
2	 *
3	 * Originally developed in 2003 / 2004 by John Good.
4	 */
5	
6	#include <stdio.h>
7	#if defined(_MSC_VER)
8	  #define _USE_MATH_DEFINES
9	#endif
10	#include <math.h>
11	#include "mNaN.h"
12	#include "overlapArea.h"
13	
14	// Constants
15	
16	#define FALSE             0
17	#define TRUE              1
18	#define FOREVER           1
19	
20	#define COLINEAR_SEGMENTS 0
21	#define ENDPOINT_ONLY     1
22	#define NORMAL_INTERSECT  2
23	#define NO_INTERSECTION   3
24	
25	#define CLOCKWISE         1
26	#define PARALLEL          0
27	#define COUNTERCLOCKWISE -1
28	
29	#define UNKNOWN           0
30	#define P_IN_Q            1
31	#define Q_IN_P            2
32	
33	#if defined(DEBUG_OVERLAP_AREA)
34	    const int DEBUG = 10;
35	#else
36	    const int DEBUG = 0;
37	#endif
38	
39	const double DEG_TO_RADIANS = M_PI / 180.;
40	// sin(x) where x = 5e-4 arcsec or cos(x) when x is within 1e-5 arcsec of 90 degrees
41	const double TOLERANCE = 4.424e-9;
42	const int NP = 4;
43	const int NQ = 4;
44	
45	typedef struct vec {
46	  double x;
47	  double y;
48	  double z;
49	} Vec;
50	
51	// Function prototypes
52	
53	int DirectionCalculator(Vec *a, Vec *b, Vec *c);
54	int SegSegIntersect(Vec *a, Vec *b, Vec *c, Vec *d, Vec *e, Vec *f, Vec *p,
55	                    Vec *q);
56	int Between(Vec *a, Vec *b, Vec *c);
57	int Cross(Vec *a, Vec *b, Vec *c);
58	double Dot(Vec *a, Vec *b);
59	double Normalize(Vec *a);
60	void Reverse(Vec *a);
61	void SaveVertex(Vec *a, Vec *P, Vec *Q, Vec *V, int *nv);
62	void SaveSharedSeg(Vec *p, Vec *q, Vec *P, Vec *Q, Vec *V, int *nv);
63	
64	void ComputeIntersection(Vec *P, Vec *Q, Vec *V, int *nv);
65	void EnsureCounterClockWise(Vec *V);
66	
67	int UpdateInteriorFlag(Vec *p, int interiorFlag, int pEndpointFromQdir,
68	                       int qEndpointFromPdir, Vec *P, Vec *Q, Vec *V, int *nv);
69	
70	int Advance(int i, int *i_advances, int n, int inside, Vec *v, Vec *P, Vec *Q, Vec *V, int *nv);
71	
72	double Girard(int nv, Vec *V);
73	void RemoveDups(int *nv, Vec *V);
74	
75	int printDir(char *point, char *vector, int dir);
76	
77	/*
78	 * Sets up the polygons, runs the overlap computation, and returns the area of overlap.
79	 */
80	double computeOverlap(double *ilon, double *ilat, double *olon, double *olat,
81	                      int energyMode, double refArea, double *areaRatio) {
82	  int i;
83	  double thisPixelArea;
84	  Vec P[8], Q[8], V[16];
85	  int nv;
86	
87	  *areaRatio = 1.;
88	
89	  if (energyMode) {
90	    nv = 0;
91	
92	    for (i = 0; i < 4; ++i)
93	      SaveVertex(&P[i], P, Q, V, &nv);
94	
95	    thisPixelArea = Girard(nv, V);
96	
97	    *areaRatio = thisPixelArea / refArea;
98	  }
99	
100	  nv = 0;
101	
102	  if (DEBUG >= 4) {
103	    printf("Input (P):\n");
104	    for (i = 0; i < 4; ++i)
105	      printf("%10.6f %10.6f\n", ilon[i], ilat[i]);
106	
107	    printf("\nOutput (Q):\n");
108	    for (i = 0; i < 4; ++i)
109	      printf("%10.6f %10.6f\n", olon[i], olat[i]);
110	
111	    printf("\n");
112	    fflush(stdout);
113	  }
114	
115	  for (i = 0; i < 4; ++i) {
116	    P[i].x = cos(ilon[i]) * cos(ilat[i]);
117	    P[i].y = sin(ilon[i]) * cos(ilat[i]);
118	    P[i].z = sin(ilat[i]);
119	  }
120	
121	  for (i = 0; i < 4; ++i) {
122	    Q[i].x = cos(olon[i]) * cos(olat[i]);
123	    Q[i].y = sin(olon[i]) * cos(olat[i]);
124	    Q[i].z = sin(olat[i]);
125	  }
126	
127	  EnsureCounterClockWise(P);
128	  EnsureCounterClockWise(Q);
129	
130	  ComputeIntersection(P, Q, V, &nv);
131	
132	  return (Girard(nv, V));
133	}
134	
135	void EnsureCounterClockWise(Vec *V) {
136	
137	  // Make sure that the polygon is counter-clockwise. For now we assume that we
138	  // are dealing with convex quadrilaterals, and therefore we can just check
139	  // the two first sides of the polygon.
140	
141	  Vec S1, S2, C;
142	  double dir;
143	  double tmp;
144	
145	  S1.x = V[1].x - V[0].x;
146	  S1.y = V[1].y - V[0].y;
147	  S1.z = V[1].z - V[0].z;
148	
149	  S2.x = V[2].x - V[1].x;
150	  S2.y = V[2].y - V[1].y;
151	  S2.z = V[2].z - V[1].z;
152	
153	  Cross(&S1, &S2, &C);
154	
155	  dir = Dot(&V[1], &C);
156	
157	  if (dir < 0) {
158	    tmp = V[2].x;
159	    V[2].x = V[0].x;
160	    V[0].x = tmp;
161	    tmp = V[2].y;
162	    V[2].y = V[0].y;
163	    V[0].y = tmp;
164	    tmp = V[2].z;
165	    V[2].z = V[0].z;
166	    V[0].z = tmp;
167	  }
168	
169	}
170	
171	/*
172	 * Find the polygon defining the area of overlap
173	 * between the two input polygons P and Q.
174	 */
175	void ComputeIntersection(Vec *P, Vec *Q, Vec *V, int *nv) {
176	  Vec Pdir, Qdir;              // "Current" directed edges on P and Q
177	  Vec other;                   // Temporary "edge-like" variable
178	  int ip, iq;                  // Indices of ends of Pdir, Qdir
179	  int ip_begin, iq_begin;      // Indices of beginning of Pdir, Qdir
180	  int PToQDir;                 // Qdir direction relative to Pdir
181	                               // (e.g. CLOCKWISE)
182	  int qEndpointFromPdir;       // End P vertex as viewed from beginning
183	                               // of Qdir relative to Qdir
184	  int pEndpointFromQdir;       // End Q vertex as viewed from beginning
185	                               // of Pdir relative to Pdir
186	  Vec firstIntersection;       // Point of intersection of Pdir, Qdir
187	  Vec secondIntersection;      // Second point of intersection
188	                               // (if there is one)
189	  int interiorFlag;            // Which polygon is inside the other
190	  int contained;               // Used for "completely contained" check
191	  int p_advances, q_advances;  // Number of times we've advanced
192	                               // P and Q indices
193	  int isFirstPoint;            // Is this the first point?
194	  int intersectionCode;        // SegSegIntersect() return code.
195	
196	  // Check for Q contained in P
197	
198	  contained = TRUE;
199	
200	  for (ip = 0; ip < NP; ++ip) {
201	    ip_begin = (ip + NP - 1) % NP;
202	
203	    Cross(&P[ip_begin], &P[ip], &Pdir);
204	    Normalize(&Pdir);
205	
206	    for (iq = 0; iq < NQ; ++iq) {
207	      if (DEBUG >= 4) {
208	        printf("Q in P: Dot%d%d = %12.5e\n", ip, iq, Dot(&Pdir, &Q[iq]));
209	        fflush(stdout);
210	      }
211	
212	      if (Dot(&Pdir, &Q[iq]) < -TOLERANCE) {
213	        contained = FALSE;
214	        break;
215	      }
216	    }
217	
218	    if (!contained)
219	      break;
220	  }
221	
222	  if (contained) {
223	    if (DEBUG >= 4) {
224	      printf("Q is entirely contained in P (output pixel is in input pixel)\n");
225	      fflush(stdout);
226	    }
227	
228	    for (iq = 0; iq < NQ; ++iq)
229	      SaveVertex(&Q[iq], P, Q, V, nv);
230	
231	    return;
232	  }
233	
234	  // Check for P contained in Q
235	
236	  contained = TRUE;
237	
238	  for (iq = 0; iq < NQ; ++iq) {
239	    iq_begin = (iq + NQ - 1) % NQ;
240	
241	    Cross(&Q[iq_begin], &Q[iq], &Qdir);
242	    Normalize(&Qdir);
243	
244	    for (ip = 0; ip < NP; ++ip) {
245	      if (DEBUG >= 4) {
246	        printf("P in Q: Dot%d%d = %12.5e\n", iq, ip, Dot(&Qdir, &P[ip]));
247	        fflush(stdout);
248	      }
249	
250	      if (Dot(&Qdir, &P[ip]) < -TOLERANCE) {
251	        contained = FALSE;
252	        break;
253	      }
254	    }
255	
256	    if (!contained)
257	      break;
258	  }
259	
260	  if (contained) {
261	    if (DEBUG >= 4) {
262	      printf("P is entirely contained in Q (input pixel is in output pixel)\n");
263	      fflush(stdout);
264	    }
265	
266	    *nv = 0;
267	    for (ip = 0; ip < NP; ++ip)
268	      SaveVertex(&P[ip], P, Q, V, nv);
269	
270	    return;
271	  }
272	
273	  // Then check for polygon overlap
274	
275	  ip = 0;
276	  iq = 0;
277	
278	  p_advances = 0;
279	  q_advances = 0;
280	
281	  interiorFlag = UNKNOWN;
282	  isFirstPoint = TRUE;
283	
284	  while (FOREVER) {
285	    if (p_advances >= 2 * NP)
286	      break;
287	    if (q_advances >= 2 * NQ)
288	      break;
289	    if (p_advances >= NP && q_advances >= NQ)
290	      break;
291	
292	    if (DEBUG >= 4) {
293	      printf("-----\n");
294	
295	      if (interiorFlag == UNKNOWN) {
296	        printf("Before advances (UNKNOWN interiorFlag): ip=%d, iq=%d ", ip, iq);
297	        printf("(p_advances=%d, q_advances=%d)\n", p_advances, q_advances);
298	      }
299	
300	      else if (interiorFlag == P_IN_Q) {
301	        printf("Before advances (P_IN_Q): ip=%d, iq=%d ", ip, iq);
302	        printf("(p_advances=%d, q_advances=%d)\n", p_advances, q_advances);
303	      }
304	
305	      else if (interiorFlag == Q_IN_P) {
306	        printf("Before advances (Q_IN_P): ip=%d, iq=%d ", ip, iq);
307	        printf("(p_advances=%d, q_advances=%d)\n", p_advances, q_advances);
308	      } else
309	        printf("\nBAD INTERIOR FLAG.  Shouldn't get here\n");
310	
311	      fflush(stdout);
312	    }
313	
314	    // Previous point in the polygon
315	
316	    ip_begin = (ip + NP - 1) % NP;
317	    iq_begin = (iq + NQ - 1) % NQ;
318	
319	    // The current polygon edges are given by
320	    // the cross product of the vertex vectors
321	
322	    Cross(&P[ip_begin], &P[ip], &Pdir);
323	    Cross(&Q[iq_begin], &Q[iq], &Qdir);
324	
325	    PToQDir = DirectionCalculator(&P[ip], &Pdir, &Qdir);
326	
327	    Cross(&Q[iq_begin], &P[ip], &other);
328	    pEndpointFromQdir = DirectionCalculator(&Q[iq_begin], &Qdir, &other);
329	
330	    Cross(&P[ip_begin], &Q[iq], &other);
331	    qEndpointFromPdir = DirectionCalculator(&P[ip_begin], &Pdir, &other);
332	
333	    if (DEBUG >= 4) {
334	      printf("   ");
335	      printDir("P", "Q", PToQDir);
336	      printDir("pEndpoint", "Q", pEndpointFromQdir);
337	      printDir("qEndpoint", "P", qEndpointFromPdir);
338	      printf("\n");
339	      fflush(stdout);
340	    }
341	
342	    // Find point(s) of intersection between edges
343	
344	    intersectionCode = SegSegIntersect(&Pdir, &Qdir, &P[ip_begin], &P[ip],
345	                                       &Q[iq_begin], &Q[iq], &firstIntersection,
346	                                       &secondIntersection);
347	
348	    if (intersectionCode == NORMAL_INTERSECT
349	        || intersectionCode == ENDPOINT_ONLY) {
350	      if (interiorFlag == UNKNOWN && isFirstPoint) {
351	        p_advances = 0;
352	        q_advances = 0;
353	
354	        isFirstPoint = FALSE;
355	      }
356	
357	      interiorFlag = UpdateInteriorFlag(&firstIntersection, interiorFlag,
358	                                        pEndpointFromQdir, qEndpointFromPdir, P, Q, V, nv);
359	
360	      if (DEBUG >= 4) {
361	        if (interiorFlag == UNKNOWN)
362	          printf("   interiorFlag -> UNKNOWN\n");
363	
364	        else if (interiorFlag == P_IN_Q)
365	          printf("   interiorFlag -> P_IN_Q\n");
366	
367	        else if (interiorFlag == Q_IN_P)
368	          printf("   interiorFlag -> Q_IN_P\n");
369	
370	        else
371	          printf("   BAD interiorFlag.  Shouldn't get here\n");
372	
373	        fflush(stdout);
374	      }
375	    }
376	
377	    // Advance rules
378	
379	    // Special case: Pdir & Qdir overlap and oppositely oriented.
380	
381	    if ((intersectionCode == COLINEAR_SEGMENTS) && (Dot(&Pdir, &Qdir) < 0)) {
382	      if (DEBUG >= 4) {
383	        printf("   ADVANCE: Pdir and Qdir are colinear.\n");
384	        fflush(stdout);
385	      }
386	
387	      SaveSharedSeg(&firstIntersection, &secondIntersection, P, Q, V, nv);
388	
389	      RemoveDups(nv, V);
390	      return;
391	    }
392	
393	    // Special case: Pdir & Qdir parallel and separated.
394	
395	    if ((PToQDir == PARALLEL) && (pEndpointFromQdir == CLOCKWISE)
396	        && (qEndpointFromPdir == CLOCKWISE)) {
397	      if (DEBUG >= 4) {
398	        printf("   ADVANCE: Pdir and Qdir are disjoint.\n");
399	        fflush(stdout);
400	      }
401	
402	      RemoveDups(nv, V);
403	      return;
404	    }
405	
406	    // Special case: Pdir & Qdir colinear.
407	
408	    else if ((PToQDir == PARALLEL) && (pEndpointFromQdir == PARALLEL)
409	        && (qEndpointFromPdir == PARALLEL)) {
410	      if (DEBUG >= 4) {
411	        printf("   ADVANCE: Pdir and Qdir are colinear.\n");
412	        fflush(stdout);
413	      }
414	
415	      // Advance but do not output point.
416	
417	      if (interiorFlag == P_IN_Q)
418	        iq = Advance(iq, &q_advances, NQ, interiorFlag == Q_IN_P, &Q[iq], P, Q, V, nv);
419	      else
420	        ip = Advance(ip, &p_advances, NP, interiorFlag == P_IN_Q, &P[ip], P, Q, V, nv);
421	    }
422	
423	    // Generic cases.
424	
425	    else if (PToQDir == COUNTERCLOCKWISE || PToQDir == PARALLEL) {
426	      if (qEndpointFromPdir == COUNTERCLOCKWISE) {
427	        if (DEBUG >= 4) {
428	          printf("   ADVANCE: Generic: PToQDir is COUNTERCLOCKWISE ");
429	          printf("|| PToQDir is PARALLEL, ");
430	          printf("qEndpointFromPdir is COUNTERCLOCKWISE\n");
431	          fflush(stdout);
432	        }
433	
434	        ip = Advance(ip, &p_advances, NP, interiorFlag == P_IN_Q, &P[ip], P, Q, V, nv);
435	      } else {
436	        if (DEBUG >= 4) {
437	          printf("   ADVANCE: Generic: PToQDir is COUNTERCLOCKWISE ");
438	          printf("|| PToQDir is PARALLEL, qEndpointFromPdir is CLOCKWISE\n");
439	          fflush(stdout);
440	        }
441	
442	        iq = Advance(iq, &q_advances, NQ, interiorFlag == Q_IN_P, &Q[iq], P, Q, V, nv);
443	      }
444	    }
445	
446	    else {
447	      if (pEndpointFromQdir == COUNTERCLOCKWISE) {
448	        if (DEBUG >= 4) {
449	          printf("   ADVANCE: Generic: PToQDir is CLOCKWISE, ");
450	          printf("pEndpointFromQdir is COUNTERCLOCKWISE\n");
451	          fflush(stdout);
452	        }
453	
454	        iq = Advance(iq, &q_advances, NQ, interiorFlag == Q_IN_P, &Q[iq], P, Q, V, nv);
455	      } else {
456	        if (DEBUG >= 4) {
457	          printf("   ADVANCE: Generic: PToQDir is CLOCKWISE, ");
458	          printf("pEndpointFromQdir is CLOCKWISE\n");
459	          fflush(stdout);
460	        }
461	
462	        ip = Advance(ip, &p_advances, NP, interiorFlag == P_IN_Q, &P[ip], P, Q, V, nv);
463	      }
464	    }
465	
466	    if (DEBUG >= 4) {
467	      if (interiorFlag == UNKNOWN) {
468	        printf("After  advances: ip=%d, iq=%d ", ip, iq);
469	        printf("(p_advances=%d, q_advances=%d) interiorFlag=UNKNOWN\n",
470	               p_advances, q_advances);
471	      }
472	
473	      else if (interiorFlag == P_IN_Q) {
474	        printf("After  advances: ip=%d, iq=%d ", ip, iq);
475	        printf("(p_advances=%d, q_advances=%d) interiorFlag=P_IN_Q\n",
476	               p_advances, q_advances);
477	      }
478	
479	      else if (interiorFlag == Q_IN_P) {
480	        printf("After  advances: ip=%d, iq=%d ", ip, iq);
481	        printf("(p_advances=%d, q_advances=%d) interiorFlag=Q_IN_P\n",
482	               p_advances, q_advances);
483	      } else
484	        printf("BAD INTERIOR FLAG.  Shouldn't get here\n");
485	
486	      printf("-----\n\n");
487	      fflush(stdout);
488	    }
489	  }
490	
491	  RemoveDups(nv, V);
492	  return;
493	}
494	
495	/*
496	 * Print out the second point of intersection and toggle in/out flag.
497	 */
498	int UpdateInteriorFlag(Vec *p, int interiorFlag, int pEndpointFromQdir,
499	                       int qEndpointFromPdir, Vec *P, Vec *Q, Vec *V, int *nv) {
500	  double lon, lat;
501	
502	  if (DEBUG >= 4) {
503	    lon = atan2(p->y, p->x) / DEG_TO_RADIANS;
504	    lat = asin(p->z) / DEG_TO_RADIANS;
505	
506	    printf("   intersection [%13.6e,%13.6e,%13.6e]  "
507	           "-> (%10.6f,%10.6f) (UpdateInteriorFlag)\n",
508	           p->x, p->y, p->z, lon, lat);
509	    fflush(stdout);
510	  }
511	
512	  SaveVertex(p, P, Q, V, nv);
513	
514	  // Update interiorFlag.
515	
516	  if (pEndpointFromQdir == COUNTERCLOCKWISE)
517	    return P_IN_Q;
518	
519	  else if (qEndpointFromPdir == COUNTERCLOCKWISE)
520	    return Q_IN_P;
521	
522	  else
523	    // Keep status quo.
524	    return interiorFlag;
525	}
