527	/*
528	 * Save the endpoints of a shared segment.
529	 */
530	void SaveSharedSeg(Vec *p, Vec *q, Vec *P, Vec *Q, Vec *V, int *nv) {
531	  if (DEBUG >= 4) {
532	    printf("\n   SaveSharedSeg():  from "
533	           "[%13.6e,%13.6e,%13.6e]\n",
534	           p->x, p->y, p->z);
535	
536	    printf("   SaveSharedSeg():  to   "
537	           "[%13.6e,%13.6e,%13.6e]\n\n",
538	           q->x, q->y, q->z);
539	
540	    fflush(stdout);
541	  }
542	
543	  SaveVertex(p, P, Q, V, nv);
544	  SaveVertex(q, P, Q, V, nv);
545	
546	}
547	
548	/*
549	 * Advances and prints out an inside vertex if appropriate.
550	 */
551	int Advance(int ip, int *p_advances, int n, int inside, Vec *v, Vec *P, Vec *Q, Vec *V, int *nv) {
552	  double lon, lat;
553	
554	  lon = atan2(v->y, v->x) / DEG_TO_RADIANS;
555	  lat = asin(v->z) / DEG_TO_RADIANS;
556	
557	  if (inside) {
558	    if (DEBUG >= 4) {
559	      printf("   Advance(): inside vertex "
560	             "[%13.6e,%13.6e,%13.6e] -> (%10.6f,%10.6f)n",
561	             v->x, v->y, v->z, lon, lat);
562	
563	      fflush(stdout);
564	    }
565	
566	    SaveVertex(v, P, Q, V, nv);
567	  }
568	
569	  (*p_advances)++;
570	
571	  return (ip + 1) % n;
572	}
573	
574	/*
575	 * Save the intersection polygon vertices
576	 */
577	void SaveVertex(Vec *a, Vec *P, Vec *Q, Vec *V, int *nv) {
578	  int i, i_begin;
579	  Vec Dir;
580	
581	  if (DEBUG >= 4)
582	    printf("   SaveVertex ... ");
583	
584	  // What with TOLERANCE and roundoff problems, we need to double-check
585	  // that the point to be save is really in or on the edge of both pixels P and Q.
586	
587	  for (i = 0; i < NP; ++i) {
588	    i_begin = (i + NP - 1) % NP;
589	
590	    Cross(&P[i_begin], &P[i], &Dir);
591	    Normalize(&Dir);
592	
593	    if (Dot(&Dir, a) < -1000. * TOLERANCE) {
594	      if (DEBUG >= 4) {
595	        printf("rejected (not in P)\n");
596	        fflush(stdout);
597	      }
598	
599	      return;
600	    }
601	  }
602	
603	  for (i = 0; i < NQ; ++i) {
604	    i_begin = (i + NQ - 1) % NQ;
605	
606	    Cross(&Q[i_begin], &Q[i], &Dir);
607	    Normalize(&Dir);
608	
609	    if (Dot(&Dir, a) < -1000. * TOLERANCE) {
610	      if (DEBUG >= 4) {
611	        printf("rejected (not in Q)\n");
612	        fflush(stdout);
613	      }
614	
615	      return;
616	    }
617	  }
618	
619	  if (*nv < 15) {
620	    V[*nv].x = a->x;
621	    V[*nv].y = a->y;
622	    V[*nv].z = a->z;
623	    *nv += 1;
624	  }
625	
626	  if (DEBUG >= 4) {
627	    printf("accepted (%d)\n", *nv);
628	    fflush(stdout);
629	  }
630	}
631	
632	/*
633	 * Computes whether ac is CLOCKWISE, etc. of ab.
634	 */
635	int DirectionCalculator(Vec *a, Vec *b, Vec *c) {
636	  Vec cross;
637	  int len;
638	
639	  len = Cross(b, c, &cross);
640	
641	  if (len == 0)
642	    return PARALLEL;
643	  else if (Dot(a, &cross) < 0.)
644	    return CLOCKWISE;
645	  else
646	    return COUNTERCLOCKWISE;
647	}
