799	/*
800	 * Vector cross product.
801	 */
802	int Cross(Vec *v1, Vec *v2, Vec *v3) {
803	  v3->x = v1->y * v2->z - v2->y * v1->z;
804	  v3->y = -v1->x * v2->z + v2->x * v1->z;
805	  v3->z = v1->x * v2->y - v2->x * v1->y;
806	
807	  if (fabs(v3->x) < 1.e-18 && fabs(v3->y) < 1.e-18 && fabs(v3->z) < 1.e-18)
808	    return 0;
809	
810	  return 1;
811	}
