813	/*
814	 * Vector dot product.
815	 */
816	double Dot(Vec *a, Vec *b) {
817	  double sum = 0.0;
818	
819	  sum = a->x * b->x + a->y * b->y + a->z * b->z;
820	
821	  return sum;
822	}
823	
824	/*
825	 * Normalize the vector
826	 */
827	double Normalize(Vec *v) {
828	  double len;
829	
830	  len = sqrt(v->x * v->x + v->y * v->y + v->z * v->z);
831	
832	  if (len == 0.)
833	    len = 1.;
834	
835	  v->x = v->x / len;
836	  v->y = v->y / len;
837	  v->z = v->z / len;
838	
839	  return len;
840	}
