851	/*
852	 * Use Girard's theorem to compute the area of a sky polygon.
853	 */
854	double Girard(int nv, Vec *V) {
855	  int i, j, ibad;
856	
857	  double area;
858	  double lon, lat;
859	
860	  Vec side[16];
861	  double ang[16];
862	
863	  Vec tmp;
864	
865	  double sumang, cosAng, sinAng;
866	
867	  sumang = 0;
868	
869	  if (nv < 3)
870	    return 0;
871	
872	  if (DEBUG >= 4) {
873	    for (i = 0; i < nv; ++i) {
874	      lon = atan2(V[i].y, V[i].x) / DEG_TO_RADIANS;
875	      lat = asin(V[i].z) / DEG_TO_RADIANS;
876	
877	      printf("Girard(): %3d [%13.6e,%13.6e,%13.6e] -> (%10.6f,%10.6f)\n", i,
878	             V[i].x, V[i].y, V[i].z, lon, lat);
879	
880	      fflush(stdout);
881	    }
882	  }
883	
884	  for (i = 0; i < nv; ++i) {
885	    Cross(&V[i], &V[(i + 1) % nv], &side[i]);
886	  }
887	
888	  // De-duplicate vertices that are extremely close to each other otherwise
889	  // the angles determined in the next steps are not accurate. Need to loop
890	  // backwards to avoid affecting future sides that need to be checked.
891	
892	  for (i = nv - 1; i >= 0; --i) {
893	
894	    // We don't use TOLERANCE here since it is too large for our purposes here
895	
896	    if (Dot(&side[i], &side[i]) < 1e-30) {
897	
898	      if (DEBUG >= 4) {
899	        printf("Girard(): ---------- Corner %d duplicate; "
900	               "Remove point %d -------------\n",
901	               i, i);
902	        fflush(stdout);
903	      }
904	
905	      --nv;
906	
907	      for (j = i; j < nv; ++j) {
908	        V[j].x = V[j + 1].x;
909	        V[j].y = V[j + 1].y;
910	        V[j].z = V[j + 1].z;
911	        side[j].x = side[j + 1].x;
912	        side[j].y = side[j + 1].y;
913	        side[j].z = side[j + 1].z;
914	      }
915	
916	    }
917	  }
918	
919	  if (nv < 3)
920	    return 0;
921	
922	  for (i = 0; i < nv; ++i) {
923	    Normalize(&side[i]);
924	  }
925	
926	  for (i = 0; i < nv; ++i) {
927	    Cross(&side[i], &side[(i + 1) % nv], &tmp);
928	
929	    sinAng = Normalize(&tmp);
930	    cosAng = -Dot(&side[i], &side[(i + 1) % nv]);
931	
932	    // Remove center point of colinear segments
933	
934	    ang[i] = atan2(sinAng, cosAng);
935	
936	    if (DEBUG >= 4) {
937	      if (i == 0)
938	        printf("\n");
939	
940	      printf("Girard(): angle[%d] = %13.6e -> %13.6e (from %13.6e / %13.6e)\n",
941	             i, ang[i], ang[i] - M_PI / 2., sinAng, cosAng);
942	      fflush(stdout);
943	    }
944	
945	    // Direction changes of less than a degree can be tricky
946	    if (ang[i] > M_PI - 0.0175) {
947	      ibad = (i + 1) % nv;
948	
949	      if (DEBUG >= 4) {
950	        printf("Girard(): ---------- Corner %d bad; "
951	               "Remove point %d -------------\n",
952	               i, ibad);
953	        fflush(stdout);
954	      }
955	
956	      --nv;
957	
958	      for (j = ibad; j < nv; ++j) {
959	        V[j].x = V[j + 1].x;
960	        V[j].y = V[j + 1].y;
961	        V[j].z = V[j + 1].z;
962	      }
963	
964	      return (Girard(nv, V));
965	    }
966	
967	    sumang += ang[i];
968	  }
969	
970	  area = sumang - (nv - 2.) * M_PI;
971	
972	  if (mNaN(area) || area < 0.)
973	    area = 0.;
974	
975	  if (DEBUG >= 4) {
976	    printf("\nGirard(): area = %13.6e [%d]\n\n", area, nv);
977	    fflush(stdout);
978	  }
979	
980	  return area;
981	}
