26	/*
27	 * Sets up the polygons, runs the overlap
28	 * computation, and returns the area of overlap.
29	 * This version works in pixel space rather than
30	 * on the celestial sphere.
31	 */
32	double computeOverlapPP(double *ix, double *iy, double minX, double maxX,
33	                        double minY, double maxY, double pixelArea) {
34	  int npts;
35	  double area;
36	
37	  double nx[100];
38	  double ny[100];
39	
40	  double xp[4], yp[4];
41	
42	  // Clip the input pixel polygon with the output pixel range
43	
44	  npts = rectClip(4, ix, iy, nx, ny, minX, minY, maxX, maxY);
45	
46	  // If no points, it may mean that the output is
47	  // completely contained in the input
48	
49	  if (npts < 3) {
50	    xp[0] = minX;
51	    yp[0] = minY;
52	    xp[1] = maxX;
53	    yp[1] = minY;
54	    xp[2] = maxX;
55	    yp[2] = maxY;
56	    xp[3] = minX;
57	    yp[3] = maxY;
58	
59	    if (ptInPoly(ix[0], iy[0], 4, xp, yp)) {
60	      area = pixelArea;
61	      return area;
62	    }
63	
64	    return 0.;
65	  }
66	
67	  area = polyArea(npts, nx, ny) * pixelArea;
68	
69	  return area;
70	}
