72	int rectClip(int n, double *x, double *y, double *nx, double *ny, double minX,
73	             double minY, double maxX, double maxY) {
74	  int nCurr;
75	
76	  nCurr = lineClip(n, x, y, tmpX0, tmpY0, minX, 1);
77	
78	  if (nCurr > 0) {
79	    nCurr = lineClip(nCurr, tmpX0, tmpY0, tmpX1, tmpY1, maxX, 0);
80	
81	    if (nCurr > 0) {
82	      nCurr = lineClip(nCurr, tmpY1, tmpX1, tmpY0, tmpX0, minY, 1);
83	
84	      if (nCurr > 0) {
85	        nCurr = lineClip(nCurr, tmpY0, tmpX0, ny, nx, maxY, 0);
86	      }
87	    }
88	  }
89	
90	  return nCurr;
91	}
