93	int lineClip(int n, double *x, double *y, double *nx, double *ny, double val,
94	             int dir) {
95	  int i;
96	  int nout;
97	  int last;
98	
99	  double ycross;
100	
101	  nout = 0;
102	  last = inPlane(x[n - 1], val, dir);
103	
104	  for (i = 0; i < n; ++i) {
105	    if (last) {
106	      if (inPlane(x[i], val, dir)) {
107	        // Both endpoints in, just add the new point
108	
109	        nx[nout] = x[i];
110	        ny[nout] = y[i];
111	
112	        ++nout;
113	      } else {
114	        // Moved out of the clip region, add the point we moved out
115	
116	        if (i == 0)
117	          ycross = y[n - 1]
118	              + (y[0] - y[n - 1]) * (val - x[n - 1]) / (x[0] - x[n - 1]);
119	        else
120	          ycross = y[i - 1]
121	              + (y[i] - y[i - 1]) * (val - x[i - 1]) / (x[i] - x[i - 1]);
122	
123	        nx[nout] = val;
124	        ny[nout] = ycross;
125	
126	        ++nout;
127	
128	        last = 0;
129	      }
130	    } else {
131	      if (inPlane(x[i], val, dir)) {
132	        // Moved into the clip region.
133	        // Add the point we moved in, and the end point.
134	
135	        if (i == 0)
136	          ycross = y[n - 1]
137	              + (y[0] - y[n - 1]) * (val - x[n - 1]) / (x[i] - x[n - 1]);
138	        else
139	          ycross = y[i - 1]
140	              + (y[i] - y[i - 1]) * (val - x[i - 1]) / (x[i] - x[i - 1]);
141	
142	        nx[nout] = val;
143	        ny[nout] = ycross;
144	
145	        ++nout;
146	
147	        nx[nout] = x[i];
148	        ny[nout] = y[i];
149	
150	        ++nout;
151	
152	        last = 1;
153	      } else {
154	        // Segment entirely clipped.
155	      }
156	    }
157	  }
158	
159	  return nout;
160	}
