169	double polyArea(int npts, double *nx, double *ny) {
170	  int i, inext;
171	  double area;
172	
173	  area = 0.;
174	
175	  for (i = 0; i < npts; ++i) {
176	    inext = (i + 1) % npts;
177	
178	    area += nx[i] * ny[inext] - nx[inext] * ny[i];
179	  }
180	
181	  area = fabs(area) / 2;
182	
183	  return area;
184	}
