186	int ptInPoly(double x, double y, int n, double *xp, double *yp) {
187	  int i, inext, count;
188	  double t;
189	
190	  count = 0;
191	
192	  for (i = 0; i < n; ++i) {
193	    inext = (i + 1) % n;
194	
195	    if (((yp[i] <= y) && (yp[inext] > y))
196	        || ((yp[i] > y) && (yp[inext] <= y))) {
197	      t = (y - yp[i]) / (yp[inext] - yp[i]);
198	
199	      if (x < xp[i] + t * (xp[inext] - xp[i]))
200	        ++count;
201	    }
202	  }
203	
204	  return (count & 1);
205	}

