  tol = EffectiveTolerance(P, Q);

  if (energyMode) {
    nv = 0;

    for (i = 0; i < 4; ++i)
      SaveVertex(&P[i], P, Q, V, &nv, tol);

    thisPixelArea = Girard(nv, V);

    *areaRatio = thisPixelArea / refArea;
  }

  nv = 0;

  if (DEBUG >= 4) {
    printf("Input (P):\n");
    for (i = 0; i < 4; ++i)
      printf("%10.6f %10.6f\n", ilon[i], ilat[i]);

    printf("\nOutput (Q):\n");
    for (i = 0; i < 4; ++i)
      printf("%10.6f %10.6f\n", olon[i], olat[i]);

    printf("\n");
    fflush(stdout);
  }

  EnsureCounterClockWise(P);
  EnsureCounterClockWise(Q);

  ComputeIntersection(P, Q, V, &nv, tol);

  return (Girard(nv, V));
}

