/*
 * Tests whether a point v on a great circle arc lies (within tol, in
 * radians) between endpoints a and b of the arc. The cosine comparisons
 * previously used here lose all significance below about 1e-7 radians in
 * double precision; projections onto the tangent direction vectors of the
 * arc remain meaningful down to machine precision at any scale.
 */
int Between(Vec *v, Vec *a, Vec *b, double tol) {
  Vec n, ta, tb;

  Cross(a, b, &n);

  Cross(&n, a, &ta);
  Normalize(&ta);

  Cross(b, &n, &tb);
  Normalize(&tb);

  if (Dot(v, &ta) >= -tol && Dot(v, &tb) >= -tol)
    return TRUE;
  else
    return FALSE;
}

/*
 * Tests whether a point v on the great circle through a and b lies (within
 * tol, in radians) on the arc between a and b. The vector n_ab is the
 * cross product of a and b (it need not be normalized).
 */
int OnArc(Vec *v, Vec *a, Vec *b, Vec *n_ab, double tol) {
  Vec ta, tb;

  Cross(n_ab, a, &ta);
  Normalize(&ta);

  Cross(b, n_ab, &tb);
  Normalize(&tb);

  if (Dot(v, &ta) >= -tol && Dot(v, &tb) >= -tol)
    return TRUE;
  else
    return FALSE;
}

/*
 * Angular separation of two unit vectors (sine of the angle), which
 * remains accurate for arbitrarily small separations.
 */
double ChordDistance(Vec *a, Vec *b) {
  Vec tmp;

  Cross(a, b, &tmp);
  return Normalize(&tmp);
}

/*
 * Characteristic linear size of a polygon (longest side, in radians).
 */
double PolygonScale(Vec *P) {
  int i;
  double maxsep, sep;

  maxsep = 0.;

  for (i = 0; i < NP; ++i) {
    sep = ChordDistance(&P[i], &P[(i + 1) % NP]);

    if (sep > maxsep)
      maxsep = sep;
  }

  return maxsep;
}

/*
 * Geometric tolerance (in radians) appropriate to the pair of polygons:
 * proportional to the characteristic size of the smaller one.
 */
double EffectiveTolerance(Vec *P, Vec *Q) {
  double scaleP, scaleQ, scale;

  scaleP = PolygonScale(P);
  scaleQ = PolygonScale(Q);

  scale = scaleP < scaleQ ? scaleP : scaleQ;

  return REL_TOLERANCE * scale;
}

/*
 * Vector cross product.
 */
int Cross(Vec *v1, Vec *v2, Vec *v3) {
  v3->x = v1->y * v2->z - v2->y * v1->z;
  v3->y = -v1->x * v2->z + v2->x * v1->z;
  v3->z = v1->x * v2->y - v2->x * v1->y;

  if (fabs(v3->x) < 1.e-18 && fabs(v3->y) < 1.e-18 && fabs(v3->z) < 1.e-18)
    return 0;

  return 1;
}

