#define REL_TOLERANCE 1.0e-3

// Polygons smaller than this (in radians) have their overlap computed in a
// common local tangent (gnomonic) plane rather than on the sphere. For
// mas-scale pixels every spherical plane-side test divides by the sine of
// an arcsecond-or-smaller angle, amplifying the ~1e-16 representation
// noise of the vertex components to ~1e-8 radians --- the size of the
// pixels themselves --- making the spherical intersection chase unreliable.
// In a local tangent plane all relevant quantities are differences with
// absolute errors of order 1e-16, so the overlap is recovered to machine
// precision. The planar approximation of the area differs from the true
// spherical area only by the gnomonic distortion, which is of order
// scale^2 (about 1e-7 at the limit below). At larger scales the spherical
// machinery is well conditioned and is retained unchanged.
#define TANGENT_PLANE_LIMIT (DEG_TO_RADIANS / 60.)

